// Romega ATS — Recruiter Notify
// Inbound (from Next.js notifyRecruiterOfApplication):
//   { candidateName, candidateEmail, candidatePhone, applicationCode,
//     positionTitle, recipients:[...emails], resumeUrl, recruiterEmail }
const APP = "https://rs-tool-ticketing-system-kpg782s-projects.vercel.app";
const body = ($input.first().json.body ?? $input.first().json);
const recipients = Array.isArray(body.recipients) ? body.recipients.filter(Boolean) : [];
const to = (recipients.length ? recipients : [body.recruiterEmail].filter(Boolean)).join(', ');
if (!to) { throw new Error('No recipients for recruiter notify'); }
const name = body.candidateName || 'A candidate';
const pos  = body.positionTitle || 'a position';
const code = body.applicationCode ? ` (${body.applicationCode})` : '';
const subject = `New application: ${name} — ${pos}${code}`;
const lines = [
  `A new application just came in through the Romega careers site.`,
  ``,
  `Candidate: ${name}`,
  `Email: ${body.candidateEmail || '—'}`,
  `Phone: ${body.candidatePhone || '—'}`,
  `Position: ${pos}`,
  body.applicationCode ? `Application code: ${body.applicationCode}` : null,
  ``,
  body.resumeUrl ? `Download CV / resume:\n${body.resumeUrl}` : `Resume: open the candidate in the ATS to view it.`,
  ``,
  `Open in the ATS: ${APP}/recruiting/candidates`,
].filter(x => x !== null);
return [{ json: { to, subject, body: lines.join('\n') } }];
